with open(&apos;/root/kfmv4/src/client/modules/ui.ts&apos;, &apos;r&apos;) as f:
    content = f.read()

old = &apos;&apos;&apos;    const allVisible = Array.from(document.querySelectorAll(&apos;#fileTree .tree-item&apos;)).filter(item =&gt; isNodeExpanded(item as HTMLElement)) as HTMLElement[];
    let idx = 0;
    allVisible.forEach((item, i) =&gt; { if (item === sel) idx = i; });
    const cr = container.getBoundingClientRect();
    const centerY = cr.top + cr.height / 2;
    const selRow = sel.querySelector(&apos;.tree-row&apos;) || sel;
    const selRect = selRow.getBoundingClientRect();
    const selCenter = selRect.top + selRect.height / 2;
    const scrollingUp = selCenter &gt; centerY;
    const nextIdx = scrollingUp ? Math.max(0, idx - 1) : Math.min(allVisible.length - 1, idx + 1);
    if (nextIdx !== idx) {
      moveCursorTo(allVisible[nextIdx]);
    }&apos;&apos;&apos;

new = &apos;&apos;&apos;    const allVisible = Array.from(document.querySelectorAll(&apos;#fileTree .tree-item&apos;)).filter(item =&gt; isNodeExpanded(item as HTMLElement)) as HTMLElement[];
    let idx = 0;
    allVisible.forEach((item, i) =&gt; { if (item === sel) idx = i; });
    const cr = container.getBoundingClientRect();
    const centerY = cr.top + cr.height / 2;
    const selRow = sel.querySelector(&apos;.tree-row&apos;) || sel;
    const selRect = selRow.getBoundingClientRect();
    const selCenter = selRect.top + selRect.height / 2;
    const offset = selCenter - centerY;
    const itemH = selRect.height || 32;
    // 每帧最多追的步数 = 偏移量 / 项高度，上限10
    const steps = Math.min(10, Math.max(1, Math.round(Math.abs(offset) / itemH)));
    const nextIdx = offset &gt; 0
      ? Math.max(0, idx - steps)
      : Math.min(allVisible.length - 1, idx + steps);
    if (nextIdx !== idx) {
      moveCursorTo(allVisible[nextIdx]);
    }&apos;&apos;&apos;

content = content.replace(old, new)
with open(&apos;/root/kfmv4/src/client/modules/ui.ts&apos;, &apos;w&apos;) as f:
    f.write(content)
print(&apos;done&apos;)
